select SUM(`二频次开单货量`) / SUM(`开单货量`) as `m_0`, SUM(`二频次开单货量`) / SUM(`开单货量`) as `m_1` from (select * from ( select t3.stats_date as `统计日期` , t3.plan_handover_center_code as `规划交件分拨code` , t3.plan_handover_province_area_code as `规划交件分拨所属营运区code` , t3.plan_handover_province_area_name as `规划交件分拨所属营运区名称` , t3.plan_handover_center_name as `规划交件分拨名称` , t3.kilometer_group as `公里段（枚举值）` , t3.send_weight as `开单货量` , t3.plan_loading_weight as `规划装载货量` , t3.one_frequency_send_weight as `一频次开单货量` , t3.two_frequency_send_weight as `二频次开单货量` , t3.three_frequency_send_weight as `三频次开单货量` , t3.etl_time as `写入时间` , t3.`全国频次` - t3.`剔除该区域后全国频次` as `区域贡献值` , t3.`区域频次` - t3.`剔除该分拨后区域频次` as `分拨贡献值` , 10 as `报表类型` , t3.site_path FROM (SELECT t.* , SUM(t.plan_loading_weight) OVER() / SUM(t.send_weight) OVER() AS `全国频次` , SUM(t.plan_loading_weight) OVER(partition by t.plan_handover_province_area_code) / SUM(t.send_weight) OVER(partition by t.plan_handover_province_area_code) AS `区域频次` , (SUM(t.plan_loading_weight) OVER() - t1.plan_loading_weight_province) / (SUM(t.send_weight) OVER() - t1.send_weight_province) AS `剔除该区域后全国频次` , (SUM(t.plan_loading_weight) OVER(partition by t.plan_handover_province_area_code) - t2.plan_loading_weight_center) / (SUM(t.send_weight) OVER(partition by t.plan_handover_province_area_code) - t2.send_weight_center) AS `剔除该分拨后区域频次` , t1.site_path FROM ads_trans_center_plan_transfer_cnt as t LEFT JOIN (SELECT plan_handover_province_area_code, SUM(plan_loading_weight) as plan_loading_weight_province, SUM(send_weight) as send_weight_province from ads_trans_center_plan_transfer_cnt as t WHERE t.stats_date >= '2024-01-01' AND t.stats_date <= '2025-04-13' GROUP BY plan_handover_province_area_code) as t1 ON t.plan_handover_province_area_code = t1.plan_handover_province_area_code LEFT JOIN (SELECT plan_handover_center_code, SUM(plan_loading_weight) as plan_loading_weight_center, SUM(send_weight) as send_weight_center from ads_trans_center_plan_transfer_cnt as t WHERE t.stats_date >= '2024-01-01' AND t.stats_date <= '2025-04-13' GROUP BY plan_handover_center_code) as t2 ON t.plan_handover_center_code = t2.plan_handover_center_code inner join bd_customer_area_station t1 on t.plan_handover_center_code = t1.site_code WHERE t.stats_date >= '2024-01-01' AND t.stats_date <= '2025-04-13' ) as t3 UNION ALL select t.stats_date as `统计日期` , t.plan_handover_center_code as `规划交件分拨code` , t.plan_handover_province_area_code as `规划交件分拨所属营运区code` , t.plan_handover_province_area_name as `规划交件分拨所属营运区名称` , t.plan_handover_center_name as `规划交件分拨名称` , t.kilometer_group as `公里段（枚举值）` , t.send_weight as `开单货量` , t.plan_loading_weight as `规划装载货量` , t.one_frequency_send_weight as `一频次开单货量` , t.two_frequency_send_weight as `二频次开单货量` , t.three_frequency_send_weight as `三频次开单货量` , t.etl_time as `写入时间` , null as `区域贡献值` , null as `分拨贡献值` , 20 as `报表类型` , t1.site_path from ads_trans_center_plan_transfer_cnt t inner join bd_customer_area_station t1 on t.plan_handover_center_code = t1.site_code WHERE t.stats_date >= DATE_FORMAT(DATE_SUB('2025-04-13' , INTERVAL 6 MONTH), '%Y-%m-01') ) as `table_real` where (array_length ( array_intersect( array_filter(split(`site_path`, '@'), x -> x != ""), array_filter(split(replace('@999999@', '@', ','), ','), x -> x != "")) ) > 0)) as `alias_78083191` where (((array_length ( array_intersect( array_filter(split(`site_path`, '@'), x -> x != ""), array_filter(split(replace('@999999@', '@', ','), ','), x -> x != "")) ) > 0)) and (`报表类型` = 20) and (`统计日期` >= timestamp('2026-10-25')) and (`统计日期` < timestamp('2026-11-01')))
